import json
import os

from dotenv import load_dotenv
from groq import AsyncGroq
from pydantic import BaseModel, Field, ValidationError


# Load environment variables from the project root's .env file.
load_dotenv()

MODEL = os.getenv("GROQ_MODEL", "openai/gpt-oss-20b")


# Represents one step generated by the AI planner.
class PlannedStep(BaseModel):
    title: str = Field(min_length=3, max_length=100)
    description: str = Field(min_length=5, max_length=500)
    expected_output: str = Field(min_length=3, max_length=300)


# Represents the complete plan generated for a task.
class TaskPlan(BaseModel):
    summary: str = Field(min_length=5, max_length=500)
    steps: list[PlannedStep] = Field(min_length=1, max_length=6)


async def generate_plan(instruction: str) -> TaskPlan:
    """
    Generate a structured task plan using Groq.

    This function plans tasks only. It does not execute
    external actions or claim that any actions were completed.
    """

    api_key = os.getenv("GROQ_API_KEY")

    if not api_key:
        raise RuntimeError(
            "GROQ_API_KEY is missing. Add it to the root .env file."
        )

    client = AsyncGroq(
        api_key=api_key,
        timeout=30.0,
        max_retries=1,
    )

    # Strict JSON Schema for Groq's structured output.
    # Pydantic performs additional validation after the response.
    plan_schema = {
        "type": "object",
        "properties": {
            "summary": {
                "type": "string",
            },
            "steps": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "title": {
                            "type": "string",
                        },
                        "description": {
                            "type": "string",
                        },
                        "expected_output": {
                            "type": "string",
                        },
                    },
                    "required": [
                        "title",
                        "description",
                        "expected_output",
                    ],
                    "additionalProperties": False,
                },
            },
        },
        "required": [
            "summary",
            "steps",
        ],
        "additionalProperties": False,
    }

    try:
        response = await client.chat.completions.create(
            model=MODEL,
            temperature=0.2,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "You are JARVIS, a careful AI task planner. "
                        "Convert the user's instruction into an ordered "
                        "plan containing between 1 and 6 actionable steps. "
                        "For every step, provide a short title, a clear "
                        "description of what to do, and its expected output. "
                        "Keep the plan practical, specific, and sequential. "
                        "Do not claim that any action has already happened. "
                        "You are planning only: do not execute tools, access "
                        "accounts, modify files, or invent research results."
                    ),
                },
                {
                    "role": "user",
                    "content": instruction,
                },
            ],
            response_format={
                "type": "json_schema",
                "json_schema": {
                    "name": "jarvis_task_plan",
                    "strict": True,
                    "schema": plan_schema,
                },
            },
        )

        content = response.choices[0].message.content

        if not content:
            raise RuntimeError(
                "Groq returned an empty response while generating the plan."
            )

        try:
            plan_data = json.loads(content)
        except json.JSONDecodeError as exc:
            raise RuntimeError(
                "Groq returned a response that could not be parsed as JSON."
            ) from exc

        try:
            plan = TaskPlan.model_validate(plan_data)
        except ValidationError as exc:
            raise RuntimeError(
                "Groq returned a plan that failed validation."
            ) from exc

        return plan

    finally:
        await client.close()